"""Draft shared monthly form and per-client staffed employee review requests."""
from datetime import datetime, timezone
from zoneinfo import ZoneInfo


def run_reviews(api, params):
    settings = api.extension.settings()
    if settings.get("reviews_enabled") is not True:
        raise ValueError("Monthly reviews are disabled in reviewed Hammerjack setup")
    zone = ZoneInfo(str(settings.get("timezone", "Asia/Manila")))
    month = datetime.now(zone).strftime("%Y-%m")
    month_label = datetime.strptime(month, "%Y-%m").strftime("%B %Y")
    stamp = datetime.now(timezone.utc).isoformat()

    def records(slug, portal_id=None):
        rows, cursor = [], None
        for _ in range(10):
            args = {"type_slug": slug, "limit": 200}
            if portal_id is not None:
                args["portal_id"] = portal_id
            if cursor is not None:
                args["cursor"] = cursor
            page = api.records.list(**args)
            if not isinstance(page, dict) or not isinstance(page.get("records"), list):
                raise ValueError("Unknown Records page for " + slug)
            rows.extend(page["records"])
            next_cursor = page.get("nextCursor")
            if next_cursor is None:
                return rows
            if not isinstance(next_cursor, str) or next_cursor == cursor:
                raise ValueError("Invalid Records cursor")
            cursor = next_cursor
        raise ValueError("Review population exceeds the reviewed bounded limit")

    registry = {row["data"]["sync_key"]: row for row in records("hj_sync_runs")}
    form_key = "monthly_reviews:" + month
    form_id = registry.get(form_key, {}).get("data", {}).get("review_form_id")
    if not form_id:
        created = api.forms.create_from_template(
            form_template_id=params["form_template_id"],
            values={"review_month": {"type": "text", "value": month_label}},
            name=str(settings.get("review_form_name_prefix", "Performance Review")) + " — " + month_label,
        )
        form_id = created["form_id"]
        api.records.upsert(type_slug="hj_sync_runs", key={"field": "sync_key", "value": form_key}, record={
            "title": "Monthly review form — " + month_label,
            "data": {"sync_key": form_key, "run_label": "Monthly review form — " + month_label,
                     "operation_kind": "monthly_reviews", "status": "created", "month": month,
                     "review_form_id": form_id, "started_at": stamp},
        })

    users = api.users.list()
    if not isinstance(users, list) or len(users) > 2000:
        raise ValueError("Workspace users exceed the reviewed bounded limit")
    users_by_email = {}
    for user in users:
        if user.get("email"):
            users_by_email.setdefault(str(user["email"]).strip().lower(), []).append(user)
    mappings = {row["data"].get("workspace_user_id"): row for row in records("hj_employee_map") if row["data"].get("workspace_user_id")}
    clients = api.clients.list()
    portals = api.portals.list()
    if not isinstance(clients, list) or len(clients) > 100 or not isinstance(portals, list) or len(portals) > 100:
        raise ValueError("Client or portal inventory exceeds the reviewed 100-client limit")
    by_client = {portal["clientId"]: portal for portal in portals if portal.get("clientId")}
    created_count, skipped = 0, []
    for client in clients:
        portal = by_client.get(client["id"])
        if not portal:
            skipped.append(client["id"] + ": no client portal")
            continue
        contact_id = client.get("primaryContactId")
        if not contact_id:
            skipped.append(client["id"] + ": no primary contact")
            continue
        contact = api.contacts.get(contact_id=contact_id)
        reviewers = users_by_email.get(str((contact or {}).get("email", "")).strip().lower(), [])
        if len(reviewers) > 1:
            raise ValueError("Client primary contact matches multiple Workspace identities; resolve the ambiguous reviewer before creating requests")
        if not reviewers:
            skipped.append(client["id"] + ": primary contact has no authenticated Workspace identity")
            continue
        reviewer = reviewers[0]
        portal_id = portal["portalId"]
        existing = {row["data"]["sync_key"]: row for row in records("hj_scorecards", portal_id)}
        assigned = api.employees.list(client_id=client["id"])
        if not isinstance(assigned, list) or len(assigned) > 200:
            raise ValueError("Staffing exceeds the reviewed 200-employee client limit")
        for assignment in assigned:
            mapped = mappings.get(assignment["user_id"])
            if not mapped:
                raise ValueError("Review requires an explicit reviewed Sprout mapping for " + assignment["user_id"])
            data = mapped["data"]
            system_id = data["sprout_system_id"]
            key = str(system_id) + ":" + month
            current = existing.get(key, {}).get("data", {})
            if current.get("review_item_id"):
                if current.get("review_form_attached") is not True:
                    api.workq.attach_form(todo_id=current["review_item_id"], form_id=current["review_form_id"])
                    resumed = dict(current, review_form_attached=True, synced_at=stamp)
                    api.records.upsert(type_slug="hj_scorecards", portal_id=portal_id,
                                       key={"field": "sync_key", "value": key}, record={"title": mapped["title"], "data": resumed})
                continue
            label = mapped["title"]
            materialized = api.templates.materialize(
                template_id=params["playbook_template_id"], portal_id=portal_id,
                variables={"employee": {"type": "entity", "value": {"id": assignment["user_id"], "label": label}},
                           "client_contact": {"type": "role", "value": {"kind": "user", "id": reviewer["id"], "label": reviewer.get("name") or reviewer["email"]}},
                           "review_month": {"type": "text", "value": month_label}},
            )
            item_ids = materialized.get("itemIds")
            if not isinstance(item_ids, list) or len(item_ids) != 1:
                raise ValueError("The bundled review activity template must materialize exactly one review item")
            payload = dict(current, sync_key=key, employee_name=label, sprout_system_id=system_id,
                           month=month, review_form_id=form_id, review_item_id=item_ids[0], review_form_attached=False, synced_at=stamp)
            api.records.upsert(type_slug="hj_scorecards", portal_id=portal_id,
                               key={"field": "sync_key", "value": key}, record={"title": label, "data": payload})
            api.workq.attach_form(todo_id=item_ids[0], form_id=form_id)
            payload["review_form_attached"] = True
            api.records.upsert(type_slug="hj_scorecards", portal_id=portal_id,
                               key={"field": "sync_key", "value": key}, record={"title": label, "data": payload})
            created_count += 1
    return {"month": month, "form_id": form_id, "created_count": created_count, "skipped": skipped}


result = run_reviews(api, params)
